CREATE OR REPLACE FUNCTION public.set_trial_dates_on_profile_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
  BEGIN
    IF NEW.trial_started_at IS NULL THEN
      NEW.trial_started_at := NOW();
    END IF;

    IF NEW.trial_ends_at IS NULL THEN
      NEW.trial_ends_at := COALESCE(NEW.trial_started_at, NOW()) + INTERVAL '7 days';
    END IF;

    IF NEW.is_subscribed IS NULL THEN
      NEW.is_subscribed := FALSE;
    END IF;

    RETURN NEW;
  END;
  $function$
